function update(dt){if(paused||!running)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);actor.moving=!!(dx||dy);if(actor.moving){let m=Math.hypot(dx,dy),speed=S.stats.energy<15?70:118,nx=clamp(S.player.x+dx/m*speed*dt,15,WORLD.w-15),ny=clamp(S.player.y+dy/m*speed*dt,15,WORLD.h-15),river=ny>720&&ny<948,bridge=nx>930&&nx<1060;if(!river||bridge){S.player.x=nx;S.player.y=ny}actor.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');actor.step+=dt*8;S.stats.energy=clamp(S.stats.energy-dt*.18)}actor.tool=Math.max(0,actor.tool-dt);nodes.forEach(n=>n.hit=Math.max(0,n.hit-dt));particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=100*dt;p.life-=dt});for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);shake=Math.max(0,shake-dt*24);centerCamera();S.world.minutes+=dt*2.1;C.applySurvival(S,dt*2.1);if(S.world.minutes>=1440){S.world.minutes-=1440;S.world.day++;log(`Dawn breaks on day ${S.world.day}.`)}let z=zoneAt(S.player.x,S.player.y);if(z&&!S.discovered.includes(z.id)){S.discovered.push(z.id);C.track(S,'discover',1);toast(`LOCATION DISCOVERED: ${z.name}`);log(`Mapped ${z.name}.`)}weatherTimer+=dt;if(weatherTimer>30){weatherTimer=0;let r=Math.random();S.world.weather=r<.18?'Rain':r<.26?'Cold Wind':'Clear'}if(S.world.weather==='Rain')S.stats.temperature=clamp(S.stats.temperature-dt*.015,34,38);else S.stats.temperature+=(37-S.stats.temperature)*dt*.02;saveTimer+=dt;if(saveTimer>10){g.TLS_SAVE.save(S);saveTimer=0}g.TLS_UI.hud()}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}function visible(x,y,m=100){return x>view.x-m&&x<view.x+canvas.width/view.zoom+m&&y>view.y-m&&y<view.y+canvas.height/view.zoom+m}
function terrain(){D.zones.filter(z=>z.id!=='river').forEach(z=>{rect(z.x,z.y,z.w,z.h,z.color);ctx.globalAlpha=.18;for(let x=z.x+20;x<z.x+z.w;x+=36){let yy=z.y+((x*17+z.y*3)%z.h);rect(x,yy,2,6,'#d6db91');rect(x+5,yy+4,3,3,'#294c31')}ctx.globalAlpha=1});rect(0,694,WORLD.w,280,'#b99f68');let time=performance.now()/650;ctx.beginPath();ctx.moveTo(0,716);for(let x=0;x<=WORLD.w;x+=24)ctx.lineTo(x,724+Math.sin(x/115)*11);for(let x=WORLD.w;x>=0;x-=24)ctx.lineTo(x,944+Math.sin(x/115)*11);ctx.closePath();ctx.fillStyle='#3e8690';ctx.fill();for(let x=0;x<WORLD.w;x+=42){let y=760+((x*7)%140)+Math.sin(time+x/30)*3;rect(x,y,24,2,x%84?'#68aeb4':'#9ad0c8')}for(let x=15;x<WORLD.w;x+=61){rect(x,708+Math.sin(x/115)*11,5,5,'#716c55');rect(x+15,951+Math.sin(x/115)*11,7,4,'#82775b')}rect(930,700,130,265,'#76563a');for(let y=710;y<965;y+=22)rect(934,y,122,14,y%44?'#a37645':'#8d653f');for(let x=120;x<760;x+=32){rect(x,540+Math.sin(x/50)*20,32,24,'#7c6942');rect(x,540+Math.sin(x/50)*20,32,3,'#aa8b54')}for(let i=0;i<95;i++){let x=(i*173)%WORLD.w,y=(i*277)%WORLD.h;if(y>680&&y<985)continue;rect(x,y,2,6,'#365a38');rect(x-2,y-2,6,4,i%5===0?'#e8c564':i%7===0?'#d27a83':'#73995a')}}
