function drawPlayer(){let x=S.player.x,y=S.player.y,bob=actor.moving?Math.sin(actor.step)*2:Math.sin(performance.now()/500)*.7,leg=actor.moving?Math.sin(actor.step)*4:0;ctx.fillStyle='#20382b';ctx.beginPath();ctx.ellipse(x,y+17,15,6,0,0,Math.PI*2);ctx.fill();rect(x-10+leg,y+9,8,17,'#394a3e');rect(x+2-leg,y+9,8,17,'#2d3d34');rect(x-11,y-15+bob,22,28,'#b8633e');rect(x-14,y-8+bob,5,19,'#e3ae7a');rect(x+9,y-8+bob,5,19,'#e3ae7a');rect(x-10,y-31+bob,20,18,'#edbb88');rect(x-11,y-34+bob,22,8,'#4a2f24');rect(x-13,y-31+bob,5,12,'#4a2f24');if(actor.dir==='left'||actor.dir==='right')rect(x+(actor.dir==='right'?6:-9),y-25+bob,3,3,'#243127');else{rect(x-6,y-25+bob,3,3,'#243127');rect(x+4,y-25+bob,3,3,'#243127')}rect(x-11,y-11+bob,22,4,'#d69b49');if(actor.tool){ctx.save();ctx.translate(x+(actor.dir==='left'?-13:13),y-4);ctx.rotate((actor.dir==='left'?-1:1)*(actor.tool/.38*1.5-.7));rect(-2,-24,4,29,'#885d35');rect(-8,-28,16,8,'#b9c0aa');ctx.restore()}ctx.fillStyle='#fff0b5';ctx.font='bold 7px Consolas';ctx.textAlign='center';ctx.fillText('DARWIN',x,y-42)}
function lighting(){ctx.setTransform(1,0,0,1,0,0);let hr=S.world.minutes/60,alpha=hr<5?.36:hr<7?(7-hr)*.12:hr<17?0:hr<20?(hr-17)*.08:.36;ctx.fillStyle=hr>=17&&hr<20?`rgba(145,65,24,${alpha})`:`rgba(13,27,54,${alpha})`;ctx.fillRect(0,0,canvas.width,canvas.height);let v=ctx.createRadialGradient(canvas.width/2,canvas.height/2,canvas.height*.3,canvas.width/2,canvas.height/2,canvas.height*.85);v.addColorStop(0,'#0000');v.addColorStop(1,'rgba(8,14,10,.22)');ctx.fillStyle=v;ctx.fillRect(0,0,canvas.width,canvas.height);if(S.world.weather==='Rain'){ctx.strokeStyle='#bdd4d588';for(let i=0;i<70;i++){let x=(i*71+performance.now()/12)%canvas.width,y=(i*113+performance.now()/7)%canvas.height;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-7,y+15);ctx.stroke()}}}
function draw(){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.setTransform(view.zoom,0,0,view.zoom,-view.x*view.zoom+(shake?rand(-shake,shake):0),-view.y*view.zoom+(shake?rand(-shake,shake):0));terrain();nodes.filter(n=>visible(n.x,n.y)&&n.amount>0).sort((a,b)=>a.y-b.y).forEach(drawNode);drawPlayer();particles.forEach(p=>rect(p.x,p.y,p.size,p.size,p.color));lighting();let n=nearNode(),p=document.querySelector('#prompt');p.classList.toggle('hide',!n);if(n)p.querySelector('span').textContent=n.type==='water'?'Collect untreated water':`Gather ${D.analyse[n.type]?.name||n.type}`}
