addEventListener('resize',resizeCanvas);addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='e')gather();if(k==='q')analyse();if(k==='escape')g.TLS_UI.closePanel();if(k==='+'||k==='=')view.zoom=clamp(view.zoom+.25,1.25,2.5);if(k==='-')view.zoom=clamp(view.zoom-.25,1.25,2.5)});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);document.querySelectorAll('[data-move]').forEach(b=>{let k=b.dataset.move==='up'?'w':b.dataset.move==='down'?'s':b.dataset.move==='left'?'a':'d';b.addEventListener('pointerdown',()=>keys[k]=true);['pointerup','pointercancel','pointerleave'].forEach(v=>b.addEventListener(v,()=>keys[k]=false))});g.TLS_GAME={start,get state(){return S},setPaused(v){paused=v},interact:gather,analyse,useItem,log,toast,save(){return g.TLS_SAVE.save(S)},newState(){return C.freshState(D.quests)}};
